"""OpenCode snippet package (the user relocates ``skills/`` into their own
``.opencode/skills/``) plus the Stufe-2 npm module
``dist/npm/reqogniloom-opencode/`` (``@popoboxxo/reqogniloom-opencode``).

The snippets stay config-only: OpenCode's local plugin API is
experimental-flagged and churning fast. The npm package is the exception the
plan (D5.3, S5) asks for — it ships a small plugin module that registers the
MCP server as ``remote`` (Streamable HTTP on ``/mcp/``) through OpenCode's V2
``ctx.mcp.transform`` (and the V1 config hook on the same ``/mcp/`` path), and
bundles the same SKILL.md set. Both generations connect to the Streamable HTTP
endpoint ``/mcp/``; OpenCode 1 only falls back to the SSE endpoint when the
server does not answer the Streamable HTTP POST (see
docs/clients/opencode-transport.md). The module never carries a credential: the
config holds OpenCode's ``{env:REQOGNILOOM_API_KEY}`` placeholder, not a
literal key.

Note on DOMAIN_MODEL.md: the copied SKILL.md files contain a
"../../DOMAIN_MODEL.md" relative link. The snippet package is not
self-contained — its skills/ directory is meant to be relocated by the user
into their OWN project's .opencode/skills/ (see Interfaces note), where
"../../" resolves against that project's structure, so a copied
DOMAIN_MODEL.md there would be a stale orphan. The npm package, by contrast,
is a self-contained installable module: it keeps skills/<name>/SKILL.md one
level below its root, so the same "../../DOMAIN_MODEL.md" link resolves to
the DOMAIN_MODEL.md shipped at the package root.

Everything written here is deterministic: no timestamps, sorted skill order,
and the version comes from the repo ``VERSION`` file only.
"""
import argparse
import json
import shutil
from pathlib import Path
from typing import Any

BUILD_DIR = Path(__file__).resolve().parent
REPO_ROOT = BUILD_DIR.parent.parent
SKILLS_SRC = REPO_ROOT / "dist" / "agent-skills"
DOMAIN_MODEL = REPO_ROOT / "docs" / "agent-templates" / "DOMAIN_MODEL.md"
LICENSE_FILE = REPO_ROOT / "LICENSE"
VERSION_FILE = REPO_ROOT / "VERSION"
SERVER_NAME = "reqogniloom"

#: Stufe-2 npm package (plan D5.3 / decision E2). The name is asserted by
#: ``.github/workflows/publish-npm.yml`` and ``scripts/check_plugin_packages.py``
#: reads its version, so both constants are referenced, never re-spelled.
NPM_PACKAGE_NAME = "@popoboxxo/reqogniloom-opencode"
NPM_PACKAGE_DIRNAME = "reqogniloom-opencode"
NPM_DEFAULT_OUT = REPO_ROOT / "dist" / "npm"
NPM_MODULE = "index.js"


def discover_skill_names(skills_src: Path) -> list[str]:
    """Every immediate subdirectory of skills_src that holds a SKILL.md.

    Derived rather than hardcoded: docs/agent-templates/package_skills.py owns
    the skill set, and a literal list in one builder could be updated while the
    other three silently shipped without the new skill. Sorted so repeated
    generation stays byte-for-byte deterministic.
    """
    return sorted(
        entry.name
        for entry in skills_src.iterdir()
        if entry.is_dir() and (entry / "SKILL.md").is_file()
    )


def v2_server_entry(url: str, key_env: str) -> dict[str, Any]:
    """One OpenCode V2 server entry for ``mcp.servers.<name>``.

    V2 differs from V1 in the config shape it reads: the entry lives under
    ``mcp.servers`` while V1 reads ``mcp.<name>``. Both connect to the
    Streamable HTTP endpoint ``/mcp/`` (V1 falls back to SSE only when the
    server does not answer a Streamable HTTP POST — see
    docs/clients/opencode-transport.md). The entry also disables both the OAuth
    flow (the key travels in a header, so a browser flow would dead-end) and
    codemode. ``url`` is the base URL without a path; ``key_env`` is the *name*
    of the env var holding the key, never the key itself.
    """
    return {
        "type": "remote",
        "url": f"{url}/mcp/",
        "headers": {"X-API-Key": f"{{env:{key_env}}}"},
        "oauth": False,
        "codemode": False,
    }


#: The npm module. Kept as a literal (not generated from the snippet dicts)
#: because it is JavaScript, but it pins the exact same V2 shape as
#: ``v2_server_entry`` — a mismatch would fail the parity assertions in
#: ``test_build_opencode_package.py`` rather than ship only in one artifact.
PLUGIN_MODULE_SOURCE = """\
// Generated by dist/opencode/build_opencode_package.py — do not edit by hand.
//
// ReqogniLoom OpenCode plugin: registers the MCP server as a `remote`
// (Streamable HTTP on /mcp/) and exposes the bundled skills. The module never
// carries a credential — the config holds OpenCode's {env:...} placeholder,
// which OpenCode expands at connect time. A bare {...} would be sent literally
// and rejected as an invalid key.
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SERVER_NAME = "reqogniloom";
const MCP_URL = "{env:REQOGNILOOM_MCP_URL}/mcp/";
// OpenCode 1.x reads mcp.<name> and OpenCode 2 normalizes that V1 form to
// mcp.servers. Both speak Streamable HTTP on the same /mcp/ endpoint; V1 only
// falls back to the SSE endpoint when the server does not answer the
// Streamable HTTP POST, so a single config serves both tested generations.
const API_KEY = "{env:REQOGNILOOM_API_KEY}";

//: Directory holding this package's skills/<name>/SKILL.md files.
export const skillsDir = join(
  dirname(fileURLToPath(import.meta.url)),
  "skills",
);

//: The exact server entry OpenCode V2 sees under mcp.servers.reqogniloom.
export const serverEntry = () => ({
  type: "remote",
  url: MCP_URL,
  headers: { "X-API-Key": API_KEY },
  oauth: false,
  codemode: false,
});

const mergeV1Server = (config) => {
  if (!config || typeof config !== "object") return config;
  if (!config.mcp || typeof config.mcp !== "object") config.mcp = {};
  config.mcp[SERVER_NAME] = {
    type: "remote",
    url: MCP_URL,
    headers: { "X-API-Key": API_KEY },
  };
  return config;
};

// V1 hooks factory: V1 calls the exported plugin function and uses the hooks
// it returns. Also exposed as the module's `server()` so a V2 loader that
// ignores unknown functions is unaffected.
const v1Hooks = () => ({ config: async (config) => mergeV1Server(config) });

export const ReqogniLoomPlugin = async () => v1Hooks();

export default {
  id: SERVER_NAME,

  // OpenCode 2: MCP servers are managed only through transforms. `set` adds
  // or replaces the entry, so a re-run is idempotent.
  async setup(ctx) {
    const transform = ctx && ctx.mcp && ctx.mcp.transform;
    if (typeof transform !== "function") return;
    await transform((editor) => {
      editor.set(SERVER_NAME, serverEntry());
    });
  },

  // OpenCode 1.x: loads the hooks returned by server().
  server: ReqogniLoomPlugin,
};
"""

README_SOURCE = """\
# ReqogniLoom for OpenCode

Registers a ReqogniLoom MCP server with OpenCode and ships the ReqogniLoom
process skills. OpenCode 1 and 2 both get a `remote` entry on `/mcp/`
(Streamable HTTP, `X-API-Key`); OpenCode 1 falls back to the SSE endpoint only
if the server does not answer the Streamable HTTP POST.

## Install

```bash
npm install -g @popoboxxo/reqogniloom-opencode
```

Add the plugin to your `opencode.json` (`plugin` is also accepted by OpenCode
2, which normalizes it to `plugins`):

```json
{
  "plugin": ["@popoboxxo/reqogniloom-opencode"]
}
```

Set the two environment variables OpenCode expands at connect time — never put
a key into the config file:

```bash
export REQOGNILOOM_MCP_URL="https://your-reqogniloom-host"
export REQOGNILOOM_API_KEY="<your API key>"
```

## Skills

The package bundles `skills/<name>/SKILL.md` and `DOMAIN_MODEL.md` at its root,
so the skills' `../../DOMAIN_MODEL.md` links resolve inside the installed
package. Copy `skills/*` into `~/.config/opencode/skills/` (and
`DOMAIN_MODEL.md` one level above) if you prefer a local, user-wide install.

## Verify

```bash
opencode mcp list   # -> reqogniloom connected
```
"""


def npm_package_manifest(version: str) -> dict[str, Any]:
    """The npm ``package.json`` body; deterministic, no timestamp.

    ``version`` is the repo ``VERSION`` (single source of truth, ADR-017).
    ``files`` is explicit so ``npm pack`` ships the module and skills but never
    the builder, tests or pycache that a directory-wide pack would pick up.
    """
    return {
        "name": NPM_PACKAGE_NAME,
        "version": version,
        "description": (
            "ReqogniLoom MCP server (Streamable HTTP) and SE process skills "
            "for OpenCode."
        ),
        "license": "MIT",
        "type": "module",
        "main": NPM_MODULE,
        "exports": {".": f"./{NPM_MODULE}"},
        "files": [NPM_MODULE, "skills/", "DOMAIN_MODEL.md", "README.md", "LICENSE"],
        "engines": {"node": ">=22.14"},
        "repository": {
            "type": "git",
            "url": "git+https://github.com/Popoboxxo/ReqogniLoom.git",
            "directory": f"dist/npm/{NPM_PACKAGE_DIRNAME}",
        },
        "homepage": "https://github.com/Popoboxxo/ReqogniLoom",
        "bugs": "https://github.com/Popoboxxo/ReqogniLoom/issues",
        "keywords": [
            "opencode",
            "mcp",
            "requirements-management",
            "traceability",
            "systems-engineering",
        ],
    }


def build_npm_package(npm_out: Path, skills_src: Path = SKILLS_SRC) -> Path:
    """Write the Stufe-2 npm package under ``npm_out/reqogniloom-opencode``.

    ``npm_out`` is the ``dist/npm``-style parent, not the package directory
    itself, so callers (and the CLI ``--npm-out``) name the same level the
    workflow and ``scripts/check_plugin_packages.py`` expect. Returns the
    package directory.
    """
    version = VERSION_FILE.read_text(encoding="utf-8").strip()
    package_dir = npm_out / NPM_PACKAGE_DIRNAME
    package_dir.mkdir(parents=True, exist_ok=True)

    (package_dir / "package.json").write_text(
        json.dumps(npm_package_manifest(version), indent=2) + "\n",
        encoding="utf-8",
    )
    (package_dir / NPM_MODULE).write_text(PLUGIN_MODULE_SOURCE, encoding="utf-8")
    (package_dir / "README.md").write_text(README_SOURCE, encoding="utf-8")
    shutil.copy2(LICENSE_FILE, package_dir / "LICENSE")
    # Self-contained skills: ../../DOMAIN_MODEL.md from skills/<name>/SKILL.md
    # resolves to this file at the package root.
    shutil.copy2(DOMAIN_MODEL, package_dir / "DOMAIN_MODEL.md")

    skills_out = package_dir / "skills"
    if skills_out.exists():
        shutil.rmtree(skills_out)
    for skill_name in discover_skill_names(skills_src):
        dst = skills_out / skill_name
        dst.mkdir(parents=True, exist_ok=True)
        shutil.copy2(skills_src / skill_name / "SKILL.md", dst / "SKILL.md")

    return package_dir


def build(
    out_dir: Path,
    skills_src: Path = SKILLS_SRC,
    npm_out: Path | None = None,
) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)

    (out_dir / "opencode.json.snippet").write_text(
        json.dumps(
            {
                "mcp": {
                    SERVER_NAME: {
                        "type": "remote",
                        "url": "{env:REQOGNILOOM_MCP_URL}/mcp/",
                        "headers": {"X-API-Key": "{env:REQOGNILOOM_API_KEY}"},
                    }
                }
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    (out_dir / "opencode.v2.json.snippet").write_text(
        json.dumps(
            {
                "mcp": {
                    "servers": {
                        SERVER_NAME: v2_server_entry(
                            "{env:REQOGNILOOM_MCP_URL}", "REQOGNILOOM_API_KEY"
                        )
                    }
                }
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    skills_out = out_dir / "skills"
    if skills_out.exists():
        shutil.rmtree(skills_out)
    for skill_name in discover_skill_names(skills_src):
        dst = skills_out / skill_name
        dst.mkdir(parents=True, exist_ok=True)
        shutil.copy2(skills_src / skill_name / "SKILL.md", dst / "SKILL.md")

    # Opt-in: ``npm_out`` is None for callers that only want the snippets (the
    # existing unit tests and the isolated regeneration pipeline), so they never
    # write outside their tmp tree. The CLI default still emits both artifacts.
    if npm_out is not None:
        build_npm_package(npm_out, skills_src=skills_src)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=BUILD_DIR)
    parser.add_argument("--skills-src", type=Path, default=SKILLS_SRC)
    parser.add_argument("--npm-out", type=Path, default=NPM_DEFAULT_OUT)
    args = parser.parse_args()
    build(args.out, skills_src=args.skills_src, npm_out=args.npm_out)
